import{_ as e,o as a,c as i,a5 as o}from"./chunks/framework.CXroN2RO.js";const p=JSON.parse('{"title":"ビルド構成 — Debug/Development/Release/Shipping・シンボルファイル・PDB・デバッガ","description":"","frontmatter":{"title":"ビルド構成 — Debug/Development/Release/Shipping・シンボルファイル・PDB・デバッガ","study":{"source":"C++ Wiki","status":"published","summary":"最適化・チェック・デバッグ情報・ログの違いから、Debug・Development・Release・Shippingを整理する。","section":"reference","format":"article","domain":"tools"}},"headers":[],"relativePath":"tools/build/build-configurations.md","filePath":"tools/build/build-configurations.md"}'),l={name:"tools/build/build-configurations.md"};function r(d,t,n,s,h,u){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="ビルド構成-—-debug-development-release-shipping・シンボルファイル・pdb・デバッガ" tabindex="-1">ビルド構成 — Debug/Development/Release/Shipping・シンボルファイル・PDB・デバッガ <a class="header-anchor" href="#ビルド構成-—-debug-development-release-shipping・シンボルファイル・pdb・デバッガ" aria-label="Permalink to &quot;ビルド構成 — Debug/Development/Release/Shipping・シンボルファイル・PDB・デバッガ&quot;">​</a></h1><h2 id="一言で言うと" tabindex="-1">一言で言うと <a class="header-anchor" href="#一言で言うと" aria-label="Permalink to &quot;一言で言うと&quot;">​</a></h2><p>同じソースから「<strong>何を優先するか</strong>」別に複数の成果物を作り分けるのが<strong>ビルド構成 (configuration)</strong>。最適化・チェック・デバッグ情報・ログの4軸の組み合わせです(最適化の中身は → <a href="/study/runtime/cpp-internals/optimization-and-ub.html">コンパイラ最適化・未定義動作の影響・Debug/Release・ゼロコスト抽象化</a>)。</p><h2 id="ゲーム開発の典型4構成" tabindex="-1">ゲーム開発の典型4構成 <a class="header-anchor" href="#ゲーム開発の典型4構成" aria-label="Permalink to &quot;ゲーム開発の典型4構成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>構成</th><th>最適化</th><th>assert/チェック</th><th>デバッグ情報</th><th>用途</th></tr></thead><tbody><tr><td><strong>Debug</strong></td><td>なし(-O0//Od)</td><td>全部有効</td><td>フル</td><td>ロジックのステップ実行。ゲームによっては遊べない速度</td></tr><tr><td><strong>Development</strong></td><td>あり(-O2)</td><td>有効(assert・チートメニュー・プロファイラ計測)</td><td>あり</td><td><strong>日常の開発・デバッグの主力</strong>。UEのDevelopmentがこれ</td></tr><tr><td><strong>Release/Profile</strong></td><td>あり</td><td>計測のみ残す</td><td>あり(外部保存)</td><td>性能計測(チェックのコストを排除した本番相当)</td></tr><tr><td><strong>Shipping</strong></td><td>最大+LTO</td><td>無効(クラッシュレポートのみ)</td><td><strong>PDBは生成して手元に保管</strong>(同梱しない)</td><td>出荷物</td></tr></tbody></table><ul><li>2構成(Debug/Release)しかない標準的なCMake設定に対し、ゲームは「最適化ありでデバッグもしたい」需要が強く、中間構成を足すのが通例</li><li>構成ごとの分岐はマクロで: <code>NDEBUG</code>(標準: assert無効化)、自前の <code>#if GAME_SHIPPING</code> など。<strong>構成間で挙動が変わりすぎると「Shippingでだけ出るバグ」が増える</strong>ので、ゲームロジックの分岐は最小限に</li></ul><h2 id="シンボルファイル-pdb" tabindex="-1">シンボルファイル(PDB) <a class="header-anchor" href="#シンボルファイル-pdb" aria-label="Permalink to &quot;シンボルファイル(PDB)&quot;">​</a></h2><p>コンパイラは「機械語のアドレス ⇔ ソースの行・変数名」の対応表=<strong>デバッグ情報</strong>を作れます。Windows/MSVCでは<strong>PDBファイル</strong>(別ファイル)、GCC/Clangでは実行ファイル内蔵(-g)や分離(split-dwarf)。</p><ul><li><strong>最適化とデバッグ情報は独立</strong>: <code>-O2 -g</code> は普通(Development構成の実体)。最適化で変数が消える・行が飛ぶのは情報の限界であってPDBの故障ではない</li><li><strong>Shippingの鉄則</strong>: PDBは必ず生成して<strong>ビルドごとに保管</strong>(シンボルサーバー)。ユーザーのクラッシュダンプ(スタックのアドレス列)は、<strong>そのビルドのPDBがないと解読不能</strong>。「シンボル無しのクラッシュレポート=ただの16進数」</li><li>PDBを同梱・配布しない(リバースエンジニアリングが容易になる)</li></ul><h2 id="デバッガ" tabindex="-1">デバッガ <a class="header-anchor" href="#デバッガ" aria-label="Permalink to &quot;デバッガ&quot;">​</a></h2><ul><li>Visual Studioデバッガ(Windows/コンソールの主力)、LLDB(Mac/Clang系)、GDB(Linux/GCC系)</li><li>ブレークポイント・ステップ実行・ウォッチの基本に加え、ゲーム開発で価値が高い機能: <ul><li><strong>条件付きブレーク</strong>(<code>enemyId == 42</code> のときだけ止まる)/ データブレークポイント(<strong>このアドレスに書き込んだら止まる</strong>——メモリ破壊犯の特定に絶大 → <a href="/study/runtime/memory/memory-bugs.html">メモリバグ</a>)</li><li>クラッシュダンプ(ミニダンプ)のポストモーテムデバッグ: ユーザー環境のクラッシュを、ダンプ+PDBで手元で再生</li><li>アタッチ: 起動済みのゲームプロセスに後から接続</li></ul></li><li>「printfデバッグは恥」ではない——並行・タイミング系はログの方が有効なことも多い。<strong>両刀</strong>が正解</li></ul><h2 id="c-unityとの対応" tabindex="-1">C#/Unityとの対応 <a class="header-anchor" href="#c-unityとの対応" aria-label="Permalink to &quot;C#/Unityとの対応&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Unity/C#</th><th>C++</th></tr></thead><tbody><tr><td>エディタ再生(Mono/JIT)</td><td>Debug/Development相当</td></tr><tr><td>Development Build チェックボックス</td><td>Development構成</td></tr><tr><td>IL2CPP + Release</td><td>Release/Shipping構成(このページの世界)</td></tr><tr><td>.pdb/.mdb(スクリプトデバッグ情報)</td><td>PDB(概念同一)</td></tr><tr><td>Cloud Diagnostics / Crashlytics</td><td>クラッシュダンプ+シンボルサーバー</td></tr></tbody></table><p>Unityでは構成が2〜3個に見えるが、その下でIL2CPPが吐いたC++がこのページの構成でビルドされています。</p><h2 id="unity開発者が誤解しやすい点" tabindex="-1">Unity開発者が誤解しやすい点 <a class="header-anchor" href="#unity開発者が誤解しやすい点" aria-label="Permalink to &quot;Unity開発者が誤解しやすい点&quot;">​</a></h2><ol><li>「デバッグはエディタでやるもの」— C++では<strong>Shipping相当でだけ出るバグ</strong>(最適化・タイミング・アセット差)を追う技術(ダンプ解析)が必須スキル</li><li>「PDBはビルドの副産物」— Shippingでは<strong>成果物の一部</strong>(保管しないとサポート不能)</li><li>assertは「あると安心」ではなく構成戦略の一部——Debugで大量に入れ、Shippingで消えることで、開発中の検出力と出荷物の速度を両立する(→ <a href="/study/languages/cpp/exceptions.html">契約のassert</a>)</li></ol><h2 id="実務指針" tabindex="-1">実務指針 <a class="header-anchor" href="#実務指針" aria-label="Permalink to &quot;実務指針&quot;">​</a></h2><ul><li>毎日Developmentで開発し、<strong>週次以上でShippingビルドを起動・テスト</strong>(構成差バグの早期発見)</li><li>ビルドIDをゲーム内に表示(スクショから即座にどのビルドか特定)+ PDBと紐付け</li><li>assertには<strong>メッセージと値</strong>を(<code>assert(index &lt; size &amp;&amp; &quot;enemy index out of range&quot;)</code>)</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>4構成の違いを「最適化・チェック・デバッグ情報」の3軸で言えますか。</li><li>ShippingビルドでPDBを生成・保管すべき理由は?</li><li>データブレークポイントはどんなバグに効きますか。</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p>samples/cmake_demo/ を <code>-DCMAKE_BUILD_TYPE=Debug</code> と <code>Release</code> でそれぞれビルドし、(a) 実行ファイルサイズ、(b) assertの有効/無効(NDEBUGの効果)を確認してください。</p><hr><p>関連項目：<a href="/study/tools/build/build-tools-cmake.html">ビルドツール: CMake</a> / <a href="/study/tools/build/">学習ガイド</a> / <a href="/study/tools/build/build-speed.html">ビルド時間</a></p>',24)])])}const b=e(l,[["render",r]]);export{p as __pageData,b as default};
